{"t":"node","id":"nat","product":"nat","label":"NAT Gateway","group":"vpc","why":"서버 아웃바운드 인터넷 접근"}
{"t":"edge","id":"e-game-server-nat","from":"game-server","to":"nat","kind":"control"}
